            { "set.wipe.title", new[]{ "配置重置与卸载", "Reset or Uninstall" } },
            { "set.wipe.desc", new[]{ "重置软件清空用户数据并重新打开；卸载尝试还原改动，清理自启与数据，退出后删除本体。", "Reset clears user data and reopens the app. Uninstall attempts restoration, removes startup and data, then deletes the executable after exit." } },
            { "set.reset.desc", new[]{ "清空设置、游戏库、白名单、忽略记录和日志后重新打开。保留程序、自启选择、系统环境开关与恢复记录。", "Clear preferences, library, whitelist, ignored games and logs, then reopen. Keep the app, startup choice, environment switches and recovery records." } },
            { "set.uninstall.desc", new[]{ "尝试还原 Pavise 的改动，清理自启与数据，退出后删除当前程序和托管启动副本。", "Attempt to restore Pavise changes, clear startup and data, then delete this executable and managed startup copies after exit." } },
            { "wipe.confirm", new[]{ "重置软件？\r\n\r\n游戏库、白名单、忽略记录、设置和日志将清空，完成后自动重新打开。\r\n\r\n保留程序、自启选择、系统环境开关和恢复记录。", "Reset the app?\r\n\r\nClear the library, whitelist, ignored games, preferences and logs, then reopen automatically.\r\n\r\nKeep the app, startup choice, environment switches and recovery records." } },
            { "wipe.ingame", new[]{ "对局进行中，请先退出游戏再重置软件。", "A match is in progress. Exit the game before resetting the app." } },
            { "wipe.done", new[]{ "软件数据已重置，将重新打开。", "App data has been reset. Reopening the app." } },
            { "wipe.failed", new[]{ "重置未全部完成：{0}\r\n\r\n未能清理的项目已跳过，恢复记录保留。后台已停止时会重新打开，可关闭占用程序后再试。", "Reset was incomplete: {0}\r\n\r\nUnavailable items were skipped; recovery records are retained. The app reopens once its background tasks have stopped. Close programs holding the files and retry." } },
            { "wipe.progress.stop", new[]{ "正在停止后台并完成运行收尾", "Stopping background tasks and finishing pending work" } },
            { "wipe.restartfail", new[]{ "重置已处理，但重新打开失败，请手动启动 Pavise。", "Reset has finished, but reopening failed. Start Pavise manually." } },
            { "data.operation.title", new[]{ "正在处理", "Processing" } },
