            { "wipe.stopfail", new[]{ "停止阶段：后台任务尚未确认退出，未开始清理，恢复记录已保留。", "Stop phase: background tasks have not confirmed exit. Cleanup was not started; recovery records are retained." } },
            { "wipe.pathfail", new[]{ "数据阶段：数据目录无效，未开始清理。", "Data phase: invalid data directory; cleanup was not started." } },
            { "wipe.cleanupfail", new[]{ "清理阶段发生异常，未完成重置；请保留剩余配置。", "Cleanup encountered an error. Reset is incomplete; keep remaining configuration." } },
            { "wipe.regfail", new[]{ "部分注册表设置未能清理，请重试。", "Some registry settings could not be cleared. Please retry." } },
            { "uninstall.confirm", new[]{ "卸载 Pavise？\r\n\r\n尝试还原记录中的系统改动，清理自启、游戏库、设置和日志。退出后自动删除当前程序与托管启动副本。\r\n\r\n失败项目跳过，未完成的恢复记录保留。", "Uninstall Pavise?\r\n\r\nAttempt to restore recorded system changes and clear startup, library, preferences and logs. After exit, delete this executable and managed startup copies automatically.\r\n\r\nSkip failed items and retain pending recovery records." } },
            { "uninstall.ingame", new[]{ "对局进行中 请先退出游戏再卸载", "A match is in progress. Exit the game before uninstalling." } },
            { "uninstall.done", new[]{ "还原与数据清理已完成。", "Restoration and data cleanup are complete." } },
            { "uninstall.partial", new[]{ "已完成可执行的卸载清理，跳过 {0} 个未完成项目。未完成的恢复记录已保留。", "Available uninstall work is complete; {0} unfinished items were skipped. Pending recovery records are retained." } },
            { "uninstall.selfdelete", new[]{ "关闭此提示后退出，本体与托管启动副本将自动删除。", "Close this message to exit. This executable and managed startup copies will be deleted automatically." } },
            { "uninstall.manualdelete", new[]{ "未能安排本体删除，请退出后手动删除程序。原因：{0}", "Executable deletion could not be scheduled. Delete the app manually after exit. Reason: {0}" } },
            { "uninstall.failed", new[]{ "卸载未开始清理：{0}\r\n\r\n后台尚未确认停止，数据和恢复记录保留。程序将退出。", "Uninstall cleanup did not start: {0}\r\n\r\nBackground shutdown was not confirmed. Data and recovery records are retained. The app will exit." } },
