            { "set.awake.n", new[]{ "对局中阻止息屏和睡眠，退场自动解除；不修改电源计划超时。", "Prevents display-off and sleep during matches, then releases automatically. Power-plan timeouts are unchanged." } },
            { "gm.dwmboost", new[]{ "DWM 合成调度", "DWM composition scheduling" } },
            { "gm.dwmboost.sub", new[]{ "默认关闭，无逐游戏覆盖。仅对局中生效。让桌面窗口管理器的合成线程注册进多媒体调度的实时档，无边框和窗口化游戏在 CPU 吃满时合成不被抢占。独占全屏不经合成器，此项无作用。退出对局或本程序即恢复。", "Off by default, with no per-game override. Active during play. Registers the Desktop Window Manager's composition threads into the multimedia scheduler's real-time tier, so borderless and windowed games keep compositing under full CPU load. Exclusive fullscreen bypasses the compositor and is unaffected. Restored on game exit or when Pavise closes." } },
            { "log.dwmboost.1", new[]{ "已请求 DWM 参与多媒体调度（MMCSS）", "Requested DWM participation in multimedia scheduling (MMCSS)" } },
            { "log.dwmboost.2", new[]{ "已撤销本程序的 DWM 多媒体调度请求", "Released this application's DWM multimedia scheduling request" } },
            { "gm.rsssteer", new[]{ "网络收包引离游戏核", "Steer packet processing off game cores" } },
            { "log.rsssteer.5", new[]{ "RSS 还原未完全成功 收据保留 下轮重试", "RSS restore incomplete; the receipt is kept for retry" } },
            { "log.rsssteer.6", new[]{ "RSS 收包区间已按收据还原", "RSS processing range restored from the receipt" } },
            { "gm.wstrim", new[]{ "压制后台工作集修剪", "Trim suppressed working sets" } },
            { "gm.wstrim.sub", new[]{ "默认关闭，可逐游戏覆盖。后台进程被隔离后清空一次其占用的物理内存工作集，页面转入待机列表，物理内存腾给游戏。切回该程序时按需重新载入，首次响应会变慢；每个进程实例只清一次，反作弊进程不清。", "Off by default, with per-game overrides. After a background process is isolated, its physical-memory working set is emptied once; the pages move to the standby list and the physical memory goes to the game. Switching back to that program reloads on demand, so its first response is slower. Each process instance is trimmed once; anti-cheat processes are never trimmed." } },
            { "set.memcompress", new[]{ "关闭内存压缩与页合并", "Disable memory compression and page combining" } },
            { "set.memcompress.n", new[]{ "默认关闭。停止压缩线程与页合并扫描的后台 CPU 消耗，重启后彻底生效。内存充裕的机器用不到压缩；不足 24GB 的机器不提供。关闭时只回启原本开着的项。", "Off by default. Stops the background CPU cost of the compression thread and page-combining scans; fully effective after a restart. Machines with ample memory do not need compression; unavailable below 24GB. Switching off re-enables only what was on before." } },
            { "memcompress.smallram", new[]{ "内存不足 24GB，压缩对这台机器有用，本项不提供。", "Below 24 GB of RAM compression earns its keep on this machine, so this item is unavailable." } },
            { "log.memcompress.1", new[]{ "读取内存压缩状态失败 未改动", "Reading memory compression state failed; nothing changed" } },
            { "log.memcompress.2", new[]{ "内存压缩快照写入失败 未改动", "Writing the memory compression snapshot failed; nothing changed" } },
            { "log.memcompress.3", new[]{ "关闭内存压缩未通过校验 已放弃", "Disabling memory compression failed verification; abandoned" } },
            { "log.memcompress.4", new[]{ "内存压缩与页合并已关闭 重启后彻底生效", "Memory compression and page combining disabled; fully effective after restart" } },
            { "log.memcompress.5", new[]{ "还原内存压缩未通过校验 记录保留", "Restoring memory compression failed verification; the record is kept" } },
            { "log.memcompress.6", new[]{ "内存压缩设置已按记录还原", "Memory compression settings restored from the record" } },
