            { "lib.family.suppress", new[]{ "压制家族后台", "Suppress family background" } },
            { "lib.family.on", new[]{ "开启 · 后台压制", "On · family suppression" } },
            { "lib.family.off", new[]{ "关闭 · 保留豁免", "Off · family protected" } },
            { "lib.family.gated", new[]{ "待观测 · 先进一局", "Pending · play a match first" } },
            { "lib.family.gated.body", new[]{ "这个条目还没有观测到渲染 Pavise 不确定它是不是游戏本体 先进一局 看到已观测渲染标签后再开启家族后台压制", "Rendering has not been observed for this entry yet, so Pavise cannot tell whether it is the game itself. Play a match first; once the entry shows the observed badge, family suppression can be turned on." } },
            { "lib.family.tip", new[]{ "仅对这个游戏的会话设置。关闭时保留家族及 Steam 平台辅助进程的自动保护；开启时允许符合后台规则的关联进程，以及 Steam 主程序、网页和覆盖层辅助进程被压制。游戏本体、候选、白名单及其他已确认的保护仍有效。\r\n\r\n例如用 Steam 启动 CS:GO：请选择游戏本体 EXE。需要保留 Steam 功能可将具体进程加白。OBS 等独立录屏与硬件、输入音频保护不随此项关闭。", "Applies during this game's sessions. Off retains family and Steam platform-helper protection. On allows eligible related processes, Steam, and its web/overlay helpers to be suppressed. The game itself, candidates, whitelist and other confirmed protections remain.\r\n\r\nFor example, when Steam launches CS:GO, select the game's EXE. Whitelist Steam processes you need. Independent recording tools such as OBS, hardware, input and audio protection stay enabled." } },
            { "lib.family.list.hint", new[]{ "默认保护 · 按游戏设置", "Protected by default · per game" } },
            { "lib.family.guide.title", new[]{ "先观察，再决定", "Observe, then decide" } },
            { "lib.family.guide.body", new[]{ "默认保护游戏家族。\r\n先进入实际对局，核对渲染标签；需要时再单独开启压制。", "Game families are protected by default. Play a match, review the render label, then opt in only if needed." } },
            { "lib.renderer.observed", new[]{ "已观测渲染", "Render observed" } },
            { "lib.renderer.pending", new[]{ "暂未确认", "Not confirmed" } },
            { "lib.renderer.observed.tip", new[]{ "已在当前 EXE 上观测到 GPU 3D 渲染活动。这不证明它是游戏主渲染程序，也不保证压制其他关联进程一定安全。更换入口或程序文件变化后需要重新观测。", "GPU 3D render activity was observed for this EXE. This does not prove it is the main game renderer or guarantee that suppressing related processes is safe. A changed entry or executable requires a new observation." } },
            { "lib.renderer.pending.tip", new[]{ "尚未记录当前 EXE 的渲染活动。建议先保持家族后台压制关闭，进入实际对局后再核对。", "No render activity has been recorded for this EXE yet. Keep family background suppression off, enter an actual match, then review the result." } },
            { "lib.family.warning.title", new[]{ "不建议开启家族后台压制", "Family suppression is not recommended" } },
            { "lib.family.warning.target", new[]{ "当前游戏入口 · 完整路径可复制", "Current game entry · full path can be copied" } },
            { "lib.family.warning.noexe", new[]{ "尚未指定明确的 EXE", "No specific EXE has been selected" } },
            { "lib.family.warning.body", new[]{ "通常保持关闭。开启后，关联后台以及 Steam 主程序、网页和覆盖层辅助进程不再享受这项自动豁免；仍须满足后台压制规则。可能导致加载变慢、平台聊天/浮层卡顿或依赖功能异常，每次开启都会提醒。\r\n\r\n英雄联盟应选择对局程序 League of Legends.exe。Steam 游戏以 CS:GO 为例，应选择游戏本体 EXE，而不是 Steam.exe 或大厅。即使观测到渲染，也不保证压制关联进程安全或有收益。\r\n\r\n游戏本体、候选、白名单和已确认的其他保护不变，OBS 等独立录屏及输入音频仍保护。需要保留 Steam 功能可加白；出现异常请关闭本项。", "Normally keep this off. Enabling it allows eligible related background processes, plus Steam and its web/overlay helpers, to be suppressed. Loading, platform chat, overlays or dependent features may slow down or malfunction. Confirmation is required every time.\r\n\r\nFor League of Legends, select League of Legends.exe; for Steam games such as CS:GO, select the game's EXE, not Steam.exe or a lobby. Observed rendering does not guarantee safety or performance gains.\r\n\r\nThe game itself, candidates, whitelist and other confirmed protections remain. Independent recording and input/audio protection stays enabled. Whitelist Steam processes you need; turn this off if issues occur." } },
            { "lib.family.warning.cancel", new[]{ "保持关闭（推荐）", "Keep off (recommended)" } },
            { "lib.family.warning.enable", new[]{ "仍要开启", "Enable anyway" } },
            { "lib.family.changed", new[]{ "游戏入口刚刚发生变化。已保留当前设置，请核对新入口后重新操作。", "The game entry just changed. Its current setting was kept. Review the new entry and try again." } },
            { "lib.family.save.failed", new[]{ "未能保存此设置。条目可能已更新，请核对后重试。", "This setting could not be saved. The entry may have changed; review it and try again." } },
            { "lib.family.whitelist.note", new[]{ "# 家族后台压制由游戏库逐项设置；默认保护，白名单独立生效", "# Family background suppression is set per game in the library; protected by default, with the whitelist applied independently." } },
