            { "gm.boost", new[]{ "游戏进程提优", "Game process boost" } },
            { "gm.lane", new[]{ "候选线程提优", "Candidate thread boost" } },
            { "gm.lane.sub", new[]{ "默认开启，可逐游戏关闭。按 CPU 耗时选候选，不代表帧关键线程；误选可能拖慢游戏。已生效的候选提优会维持游戏高优先级，请按相同场景对照测试。", "On by default and can be disabled per game. CPU time identifies a busy candidate, not a frame-critical thread; a wrong choice can slow the game. An active candidate boost keeps the game at High priority. Compare the same scene before keeping it enabled." } },
            { "ac.roster", new[]{ "反作弊相容名单", "Anti-cheat compatibility list" } },
